  rows.append(dict(case=e['case'],method=e['method'],source_round=t['inherited_record']['source_round']if old else 9,new_physical_run=not old,**{k:p[k]for k in ['LUT','FF','CARRY4','DSP','clock_ns','WNS_ns','WHS_ns','FF_period_ns','pass_registered_clock','wall_s']},WCE=int(v['WCE']),seed_max_delta=int(v['seed_max_delta']),MAE=float(v['MAE_at_lowbits_zero']),inputs=int(v['inputs']),physical_top=p['top'],physical_directory=p.get('physical_directory'),reused_identical_rtl=bool(e['duplicate_of'])))
