 a=dict(round=9,status='COMPLETE_AWAIT_SCORE',completed=datetime.datetime.now().astimezone().isoformat(),rows=rows,cases=cases,full_domain_final_scans=len(rows),effective_final_inputs_evaluated=sum(r['inputs']for r in rows),new_physical_jobs=len(ppa),hdl=load(Q/'state/rtl_validation.json'),engineering_repairs=load(Q/'state/engineering_repairs.json'),limits=load(Q/'configs/plan.json')['scope']);assert len(a['hdl'])==6;dump(Q/'state/analysis.json',a)
